      "id": "pms-topic-1-2",
      "code": "1.2",
      "title": "1.2. Аппаратная модель микроконтроллера. Регистры РОН, регистр флагов SREG, указатель стека SP, счетчик команд PC",
      "hours": 2,
      "sectionId": "pms-sec-1",
      "shortDescription": "32 регистра общего назначения (R0–R31), регистровые пары X, Y, Z, структура регистра статуса SREG (флаги I, T, H, S, V, N, Z, C), стек и счетчик команд PC.",
      "synopsis": {
        "summary": "Внутренняя структура процессорного ядра AVR: регистровый файл прямого доступа, регистр состояния SREG, аппаратный стек, указатель стека SP и программный счетчик PC.",
        "keyPoints": [
          "32 8-битных регистра общего назначения (РОН / GPR) R0–R31, соединенных напрямую с обоими входами АЛУ.",
          "16-битные регистры-указатели X (R27:R26), Y (R29:R28) и Z (R31:R30) для косвенной адресации ОЗУ и Flash-памяти.",
          "Регистр состояния SREG (Status Register): 8 статусных флагов: C (перенос), Z (нуль), N (отрицательное число), V (переполнение со знаком), S (знак S=N⊕V), H (полуперенос), T (временное хранение бита), I (глобальное разрешение прерываний).",
          "Счетчик команд PC (Program Counter): хранит адрес Flash-памяти для следующей исполняемой команды.",
          "Стек (Stack): область LIFO в оперативной памяти SRAM. Указатель стека SP (Stack Pointer: SPH:SPL), автоматическая инициализация стека в `RAMEND`."
        ],
        "content": "### 1. Регистровый файл общего назначения (РОН)\nВ микроконтроллерах AVR реализован мощный регистровый файл из **32 регистров общего назначения (R0–R31)**:\n- Все 32 регистра подключены к входам и выходам АЛУ, что позволяет выполнить операцию между двумя любыми регистрами за один такт (например, `ADD R16, R17`).\n- Регистры R16–R31 (старшая половина) поддерживают работу с непосредственными константами (команда `LDI`).\n- Три пары старших регистров объединены в **16-битные адресные регистры-указатели**:\n  - Регистр **X**: `R27:R26` (XH:XL)\n  - Регистр **Y**: `R29:R28` (YH:YL)\n  - Регистр **Z**: `R31:R30` (ZH:ZL) — используется для адресации таблиц во Flash-памяти (`LPM`) и косвенных переходов (`IJMP`, `ICALL`).\n\n### 2. Регистр состояния процессора SREG\nРегистр SREG отображает результаты последней выполненной арифметико-логической операции:\n- **Бит 7 — I (Global Interrupt Enable)**: глобальный переключатель прерываний (команды `SEI` — включить, `CLI` — выключить).\n- **Бит 6 — T (Bit Copy Storage)**: бит временного хранения при битовых манипуляциях (`BST`, `BLD`).\n- **Бит 5 — H (Half Carry Flag)**: флаг половинного переноса из младшей тетрады (бита 3 в бит 4), используется для двоично-десятичной (BCD) коррекции.\n- **Бит 4 — S (Sign Bit)**: знаковый флаг, вычисляется как исключающее ИЛИ: $S = N \\oplus V$.\n- **Бит 3 — V (Two's Complement Overflow Indicator)**: флаг переполнения знакового диапазона.\n- **Бит 2 — N (Negative Flag)**: флаг отрицательного числа (копия старшего 7-го бита результата).\n- **Бит 1 — Z (Zero Flag)**: флаг нуля. Устанавливается в 1, если результат операции равен 0 (критичен для команд условных переходов `BREQ`, `BRNE`).\n- **Бит 0 — C (Carry Flag)**: флаг переноса из старшего разряда (переполнение 8-битного диапазона при сложении `ADD` или заем при вычитании `SUB`).\n\n### 3. Счетчик команд (PC) и указатель стека (SP)\n- **Program Counter (PC)**: программный счетчик содержит адрес текущей команды во Flash. При выполнении команды автоматически увеличивается на 1 или 2, либо перезаписывается при переходах (`JMP`, `CALL`, `RET`).\n- **Стек (Stack)**: организуется по принципу LIFO (Last In — First Out). Служит для сохранения адреса возврата при вызове подпрограмм (`CALL` / `RET`) и прерываний, а также для временного сохранения регистров (`PUSH` / `POP`).\n- **Указатель стека SP (SPH:SPL)**: указывает на текущую вершину стека в памяти SRAM. В микроконтроллерах AVR стек растет **сверху вниз** (от старших адресов к младшим). Первой командой любой программы на Ассемблере обязана быть инициализация стека на конец памяти:\n  ```asm\n  ldi r16, low(RAMEND)\n  out SPL, r16\n  ldi r16, high(RAMEND)\n  out SPH, r16\n  ```",
        "intuitSourceRef": "http://intuit.ru/studies/courses/541/397/lecture/9183"
      },
