        "content": "### Цель работы\nОсвоить методику схемотехнического моделирования и интерактивной симуляции микропроцессорных устройств на базе микроконтроллеров семейства AVR в среде САПР Proteus VSM.\n\n### Порядок выполнения работы:\n1. Запустите комплекс Proteus и создайте новый проект с именем `LR_1_PMS_Familiya`.\n2. В библиотеке компонентов (Pick Devices) найдите и добавьте компоненты:\n   - `ATMEGA328P`\n   - `RES` (резистор 330 Ом)\n   - `LED-GREEN` (светодиод зеленый)\n   - `BUTTON` (кнопка тактовая)\n3. Разместите микроконтроллер на листе чертежа.\n4. Подключите катод светодиода к общему проводу `GROUND`, а анод через резистор 330 Ом — к ножке `PB5` (SCK).\n5. К выводу `PC6/RESET` подключите кнопку на землю и подтягивающий резистор 10 кОм к терминалу `POWER`.\n6. Откройте свойства микроконтроллера двойным щелчком ЛКМ:\n   - В поле *CKSEL Fuses* укажите *(1111) Ext. Crystal 8.0- MHz*.\n   - В поле *Clock Frequency* введите `16000000` (16 МГц).\n   - В поле *Program File* укажите путь к готовому бинарному файлу `Blink.hex`.\n7. Запустите симуляцию нажатием кнопки Play.\n8. Убедитесь в периодическом мигании светодиода с частотой 1 Гц (период 1 секунда).\n9. Подключите виртуальный осциллограф к выводу PB5 и измерьте точную длительность импульса свечения и паузы. Сохраните проект `LR_1_PMS_Familiya.pdsprj`.",
