        "content": "### Цель работы\nИзучить внутреннюю архитектуру процессорного ядра AVR, организацию регистрового файла общего назначения, регистра флагов состояния SREG и стековой памяти с помощью пошаговой отладки в среде Microchip Studio.\n\n### Порядок выполнения работы:\n1. Запустите Microchip Studio и создайте проект на языке Ассемблер.\n2. Введите тестовую программу:\n   ```asm\n   .include \"m328Pdef.inc\"\n   .cseg\n   .org 0x0000\n   rjmp start\n   start:\n       ldi r16, low(RAMEND)\n       out SPL, r16\n       ldi r16, high(RAMEND)\n       out SPH, r16\n       \n       ldi r16, 0xFF\n       ldi r17, 0x01\n       add r16, r17      ; 0xFF + 0x01 = 0x00, флаги Z=1, C=1, H=1\n       \n       rcall my_func\n   loop:\n       rjmp loop\n   my_func:\n       push r16\n       pop r16\n       ret\n   ```\n3. Установите инструмент отладки: *Project Properties -> Tool -> Simulator*.\n4. Нажмите Alt+F5 (Start Debugging and Break).\n5. Откройте окна: *Debug -> Windows -> Processor Status* и *Registers*.\n6. Нажимая клавишу F11, выполните инициализацию стека. Зафиксируйте в отчете значение указателя стека SP (`0x08FF`).\n7. Выполните команду сложения `add r16, r17`. Обратите внимание, как регистр R16 обнулился, а в окне флагов SREG флаги `Z` (Zero) и `C` (Carry) окрасились в красный цвет (установились в 1).\n8. Сделайте шаг в функцию `rcall my_func` и проследите, как значение SP уменьшилось на 2 байта из-за сохранения 16-битного адреса возврата PC.\n9. Зафиксируйте скриншоты окон отладчика и оформите отчет.",
