          "Форматы прошивок: Intel HEX (.hex — текстовые шестнадцатеричные строки с контрольной суммой), ELF/DWARF (бинарный файл с отладочной символьной информацией).",
          "Интерфейс внутрисхемного программирования ISP (In-System Programming): выводы MOSI, MISO, SCK, RESET, VCC, GND.",
