      "id": "pms-topic-3-1",
      "code": "3.1",
      "title": "3.1. Программная модель микроконтроллера. Поля предложений на языке Ассемблер",
      "hours": 2,
      "sectionId": "pms-sec-3",
      "shortDescription": "Синтаксис ассемблерной строки: метка (Label), мнемоника команды (Mnemonic), операнды (Operands), комментарий. Числовые системы счисления.",
      "synopsis": {
        "summary": "Основы машинно-ориентированного программирования: структура ассемблерного исходного текста, правила синтаксиса, системы счисления (двоичная, шестнадцатеричная, десятичная), назначение меток.",
        "keyPoints": [
          "Язык Ассемблера: символьное представление машинного двоичного кода инструкций процессора.",
          "Четыре поля строки программы: [Метка:] <Мнемоника> [Операнды] [; Комментарий].",
          "Метка (Label): символическое имя адреса памяти команд или данных (заканчивается двоеточием).",
          "Мнемоника (Mnemonic): буквенное сокращение английских слов операции (ADD, SUB, LDI, OUT, RJMP).",
          "Операнды: регистры (R16), адреса портов (PORTB), числовые константы.",
          "Синтаксис систем счисления: десятичные (100), шестнадцатеричные (0x64 или $64), двоичные (0b01100100)."
        ],
        "content": "### 1. Архитектура ассемблерного предложения\nКаждая строка исходного файла на языке Ассемблер транслируется ровно в одну машинную инструкцию процессора (либо директиву транслятора):\nСтрока состоит из четырех четко разделенных полей:\n```asm\nметка:    мнемоника    операнд1, операнд2    ; комментарий\nloop:     ldi          r16, 0xAA             ; загрузка константы\n```\n1. **Поле метки (Label)**:\n   - Располагается с первой позиции строки, завершается двоеточием (`:`).\n   - Метка связывается транслятором с текущим адресом ячейки памяти программ (Flash) или данных (SRAM).\n   - Служит целью для команд условных и безусловных переходов (`rjmp loop`, `breq exit`).\n2. **Поле мнемоники (Mnemonic)**:\n   - Сокращенное мнемоническое имя операции (`LDI` — Load Immediate, `SUB` — Subtract, `RET` — Return).\n3. **Поле операндов (Operands)**:\n   - В зависимости от команды содержит 0, 1 или 2 операнда, разделенных запятой.\n   - В двухоперандных командах AVR **первый операнд всегда является приемником результата** (Destination), а **второй — источником** (Source):\n     `add Rd, Rr` $\\implies R_d \\leftarrow R_d + R_r$.\n4. **Поле комментария (Comment)**:\n   - Начинается с точки с запятой (`;`) и продолжается до конца строки. Игнорируется ассемблером.\n\n### 2. Системы счисления констант в ассемблере\n- **Десятичная**: `125`, `-45`\n- **Шестнадцатеричная**: префикс `0x` или `$`: `0xFF`, `$3A`\n- **Двоичная**: префикс `0b`: `0b10100101` (наиболее наглядна при формировании битовых масок портов)\n- **Символьная**: в одинарных кавычках `'A'` (транслируется в ASCII-код 65).",
        "intuitSourceRef": "http://intuit.ru/studies/courses/541/397/lecture/9188"
      },
