        "content": "### Цель лабораторной работы\nИзучить интерфейс симулятора среды разработки Microchip Studio (Atmel Studio), освоить процесс компиляции и пошаговой отладки линейных ассемблерных программ, изучить реакцию статусных флагов регистра SREG на арифметические операции над двоичными числами.\n\n### Ключевые этапы выполнения\n1. **Создание проекта**: Выбор шаблона `AVR Assembler Project`, выбор контроллера `ATmega328P`.\n2. **Ввод исходного кода**: Набор директив подключения заголовочного файла, вектора сброса, инициализации стека и тестовых инструкций `ldi`, `mov`, `add`, `sub`.\n3. **Запуск симуляции**: Запуск режима `Start Debugging and Break`.\n4. **Анализ состояний процессора**:\n   - Отслеживание содержимого регистров РОН в окне `Registers`.\n   - Проверка изменения флагов Z, C, N, V при переполнении и вычитании.\n5. **Оформление отчета**: Составление таблицы состояний регистров после каждого такта симуляции.",
