      "code": "4.4",
      "title": "4.4. Оптимизация прошивки по скорости и объему Flash-памяти в компиляторе AVR-GCC",
      "hours": 2,
      "sectionId": "pms-sec-4",
      "shortDescription": "Уровни оптимизации (-O0, -O1, -O2, -Os), размещение констант во Flash через PROGMEM, pgm_read_byte, атрибуты функций, оптимизация циклов.",
      "synopsis": {
        "summary": "Методы эффективного использования ресурсов микроконтроллера. Размещение неизменяемых таблиц, строк и шрифтов во Flash-памяти вместо SRAM с помощью макроса PROGMEM библиотеки <avr/pgmspace.h>. Уровни оптимизации компилятора.",
        "keyPoints": [
          "По умолчанию строки и константные массивы в Си при старте копируются из Flash в драгоценную память SRAM.",
          "Использование макроса PROGMEM из <avr/pgmspace.h> оставляет константы исключительно во Flash-памяти.",
          "Чтение данных из Flash-памяти во время выполнения требует специализированных функций: pgm_read_byte(), pgm_read_word(), pgm_read_float().",
          "Макрос F('Строка') в строковых операциях сохраняет текстовые литералы во Flash.",
          "Флаг оптимизации -Os (Optimize for size) является стандартом для AVR, генерируя минимальный размер бинарного файла.",
          "Флаг -O2 максимизирует быстродействие, но может раздуть код за счет агрессивного разворачивания циклов (loop unrolling)."
        ],
        "content": "### 1. Проблема расхода оперативной памяти на константы\nВ архитектуре фон Неймана константы и переменные читаются из одной памяти. В архитектуре AVR ядро не может прочитать данные из Flash обычной ассемблерной инструкцией `LD` (требуется специальная инструкция `LPM`).\nПо этой причине стандартный код Си:\n```c\nconst char message[] = \"System Initialized Successfully!\";\n```\nпри старте контроллера кодом инициализации CRT (C Runtime) **полностью копируется в оперативную память (SRAM)**! Несколько длинных строк или графических таблиц шрифтов могут мгновенно переполнить все доступные 1-2 Кб ОЗУ.\n\n### 2. Библиотека <avr/pgmspace.h> и макрос PROGMEM\nЧтобы жестко зафиксировать неизменяемые данные во Flash-памяти и не тратить ни одного байта SRAM, используется модификатор `PROGMEM`:\n```c\n#include <avr/pgmspace.h>\n\n// Массив сохраняется только во Flash!\nconst uint8_t sin_table[256] PROGMEM = { 0, 1, 3, 6, 10, 0 };\nconst char welcome_str[] PROGMEM = \"Welcome to Microcontroller OS\";\n```\n\n### 3. Чтение данных из Flash во время выполнения\nПроцессор не может прочитать массив из `PROGMEM` обычной операцией `sin_table[i]`. Для этого используются функции чтения Flash:\n```c\nuint8_t value = pgm_read_byte(&(sin_table[index]));\nuint16_t word = pgm_read_word(&(words_table[index]));\n\n// Для вывода строк по указателю:\nvoid UART_Print_P(const char *progmem_str) {\n    char c;\n    while ((c = pgm_read_byte(progmem_str++)) != '\\0') {\n        UART_SendByte(c);\n    }\n}\n```\n\n### 4. Флаги оптимизации компилятора AVR-GCC\n- `-O0`: Оптимизация отключена. Используется исключительно для пошаговой отладки при возникновении трудноуловимых логических ошибок.\n- `-O1`: Базовая оптимизация без существенного изменения структуры кода.\n- `-O2`: Высокая оптимизация по скорости (может значительно увеличить размер файла hex).\n- `-Os`: Оптимизация по размеру бинарного кода (Size). Самый рекомендуемый и общепринятый стандарт для встраиваемых систем AVR.",
        "intuitSourceRef": "https://intuit.ru/studies/courses/microprocessors_pms"
      },
