        "content": "### Цель лабораторной работы\nОсвоить методику разработки встраиваемых программ на языке Си в среде Microchip Studio, изучить правила конфигурации тактовой частоты микроконтроллера, научиться компилировать проект в исполняемый hex-файл и проводить верификацию работы устройства в среде схемотехнического моделирования Proteus VSM.\n\n### Ключевые этапы выполнения\n1. **Создание и настройка проекта**:\n   - Создание решения `GCC C Executable Project` для микроконтроллера `ATmega328P`.\n   - Настройка оптимизации компилятора на уровень `-Os`.\n2. **Написание исходного кода**:\n   ```c\n   #define F_CPU 16000000UL\n   #include <avr/io.h>\n   #include <util/delay.h>\n\n   int main(void) {\n       DDRB |= (1 << PB5); // Настройка PB5 (Arduino Pin 13) на вывод\n       while (1) {\n           PORTB ^= (1 << PB5); // Инверсия светодиода\n           _delay_ms(500);       // Задержка 500 миллисекунд\n       }\n   }\n   ```\n3. **Компиляция проекта**: Анализ отчета сборщика (Program Memory Usage, Data Memory Usage).\n4. **Моделирование в Proteus**:\n   - Создание схемы: ATmega328P, токоограничивающий резистор 330 Ом, светодиод, подключенный к PB5.\n   - Загрузка скомпилированного .hex файла в свойства микроконтроллера.\n   - Проверка частоты мигания светодиода с помощью виртуального осциллографа.",
