        "content": "### Цель лабораторной работы\nИзучить схемотехнические особенности сопряжения дискретных полупроводниковых излучателей (светодиодов) с портами ввода-вывода микроконтроллера, освоить приемы генерации динамических световых последовательностей средствами языка Си.\n\n### Ключевые этапы выполнения\n1. **Схемотехническое проектирование в Proteus**:\n   - Подключение 8 светодиодов через токоограничительные резисторные сборки (Network Resistors 330 Ом) к выводам `PD0-PD7`.\n2. **Программная реализация**:\n   - Настройка направления порта `DDRD = 0xFF;`.\n   - Написание функций генерации эффектов:\n     * Одиночный бегущий огонь: сдвиг `1 << step`.\n     * Накопление столбика светодиодов (Bargraph).\n     * Бегущая тень (инвертированная маска).\n3. **Оптимизация кода**:\n   - Вынесение шаблонов свечения в массив во Flash-памяти (`PROGMEM`).\n4. **Верификация**: Проверка стабильности интервалов переключения в симуляторе.",
