        "content": "### Цель лабораторной работы\nИзучить схемотехническую организацию и алгоритмы создания часов реального времени на базе асинхронного таймера, освоить работу с низкочастотными кварцевыми резонаторами.\n\n### Ключевые этапы выполнения\n1. **Схемотехника**:\n   - Подключение часового кварца 32.768 кГц к пинам `TOSC1 (PB6)` и `TOSC2 (PB7)`.\n2. **Асинхронная инициализация Timer2**:\n   - Перевод Timer2 в асинхронный режим: `ASSR |= (1 << AS2);`.\n   - Ожидание готовности регистров через флаги `TCR2BUB`, `TCN2UB`.\n   - Выбор предделителя 128: `TCCR2B = (1 << CS22) | (1 << CS20);`.\n   - Разрешение прерывания по переполнению: `TIMSK2 |= (1 << TOIE2);`.\n3. **Обработчик прерывания**:\n   - Инкремент структуры времени `Time_t { hours, minutes, seconds }`.\n4. **Отображение**: Вывод текущего времени в формате `HH:MM` на 4-разрядный семисегментный дисплей.",
