        "content": "### Цель лабораторной работы\nИзучить принципы пропорционального импульсного управления модельными сервоприводами, освоить высокоточное формирование управляющих таймингов с помощью 16-битного таймера.\n\n### Ключевые этапы выполнения\n1. **Расчет параметров Timer1 для сервопривода**:\n   - $F_{CPU} = 16$ МГц, предделитель $N = 8$. Частота счета таймера $f = 2$ МГц (шаг 0.5 мкс).\n   - Для периода 20 мс (50 Гц) необходимо отсчитать $20000$ мкс $/ 0.5$ мкс $= 40000$ тиков.\n   - Задаем верхний предел: $ICR1 = 40000 - 1 = 39999$.\n   - Диапазон регистра сравнения $OCR1A$:\n     * 1.0 мс (0 градусов) = $1000 / 0.5 = 2000$.\n     * 1.5 мс (90 градусов) = $1500 / 0.5 = 3000$.\n     * 2.0 мс (180 градусов) = $2000 / 0.5 = 4000$.\n2. **Схема в Proteus**:\n   - Подключение виртуального сервомотора `MOTOR-SERVO` к выводу `PB1 (OC1A)`.\n3. **Реализация плавного движения**:\n   - Плавный поворот вала от 0 до 180 градусов и обратно в цикле.",
