      "id": "pms-topic-lr17",
      "code": "ЛР 17",
      "title": "Лабораторная работа № 17 «Разработка управляющей программы последовательного интерфейса»",
      "hours": 2,
      "sectionId": "pms-sec-5",
      "shortDescription": "Реализация кольцевого приемного буфера (Ring Buffer) на прерываниях USART_RX_vect, эхо-тест, передача строк на ПК через терминал Virtual Terminal.",
