      "hours": 2,
      "sectionId": "pms-sec-5",
      "shortDescription": "Каскадируемый сдвиговый регистр 74HC595 (Serial-In Parallel-Out), передача 8/16 бит по 3 проводам (DS, SH_CP, ST_CP), расширение выходов.",
