        "content": "### Цель лабораторной работы\nИзучить схемотехнику и алгоритмы расширения параллельных портов ввода-вывода с использованием недорогих сдвиговых регистров, освоить каскадирование микросхем логики.\n\n### Ключевые этапы выполнения\n1. **Схемотехника в Proteus**:\n   - Две каскадно соединенные микросхемы `74HC595`.\n   - Линии МК: `Data (PD2)`, `Clock (PD3)`, `Latch (PD4)`.\n   - К 16 выходам регистров подключены светодиодные шкалы.\n2. **Программная реализация**:\n   - Функция передачи 16-битного слова:\n   ```c\n   void ShiftOut_16(uint16_t data) {\n       PORTD &= ~(1 << PD4); // Latch LOW\n       for (uint8_t i = 0; i < 16; i++) {\n           PORTD &= ~(1 << PD3); // Clock LOW\n           if (data & (1 << (15 - i))) PORTD |= (1 << PD2);\n           else PORTD &= ~(1 << PD2);\n           PORTD |= (1 << PD3);  // Clock HIGH (сдвиг бита)\n       }\n       PORTD |= (1 << PD4);  // Latch HIGH (мгновенный вывод всех 16 бит!)\n   }\n   ```\n3. **Моделирование**: Проверка анимации бегущих огней на 16 светодиодах.",
